import re
from typing import NamedTuple


class TemplateError(Exception):
    """Base exception for template errors."""
    pass


class TemplateSyntaxError(TemplateError):
    """Error during parsing/tokenizing."""
    def __init__(self, message: str, lineno: int):
        self.message = message
        self.lineno = lineno
        super().__init__(self)

    def __str__(self):
        return f"line {self.lineno}: {self.message}"


class TemplateRenderError(TemplateError):
    """Error during rendering."""
    def __init__(self, message: str, lineno: int):
        self.message = message
        self.lineno = lineno
        super().__init__(self)

    def __str__(self):
        return f"line {self.lineno}: {self.message}"


class Token(NamedTuple):
    kind: str
    value: str
    lineno: int

# Regex patterns for tag delimiters
TAG_START_VAR = re.compile(r'{{')
TAG_START_BLOCK = re.compile(r'{%')
TAG_START_COMMENT = re.compile(r'{#')

TAG_END_VAR = '}}'
TAG_END_BLOCK = '%}'
TAG_END_COMMENT = '#}'


def tokenize(source: str) -> list[Token]:
    """
    Tokenize the source template string.

    Returns a list of Token objects.
    Raises TemplateSyntaxError if a tag is not closed.
    """
    tokens = []
    pos = 0
    lineno = 1
    length = len(source)

    while pos < length:
        # Check for start of a tag
        is_tag = False
        tag_start_match = None

        # We need to find the earliest tag start
        m_var = TAG_START_VAR.search(source, pos)
        m_block = TAG_START_BLOCK.search(source, pos)
        m_comment = TAG_START_COMMENT.search(source, pos)

        starts = []
        if m_var:
            starts.append((m_var.start(), 'var', m_var.group()))
        if m_block:
            starts.append((m_block.start(), 'block', m_block.group()))
        if m_comment:
            starts.append((m_comment.start(), 'comment', m_comment.group()))

        if not starts:
            # No more tags, rest is text
            text = source[pos:]
            tokens.append(Token("text", text, lineno))
            break

        # Sort by position
        starts.sort(key=lambda x: x[0])

        earliest_pos, tag_type, tag_str = starts[0]

        # If there is text before this tag
        if earliest_pos > pos:
            text = source[pos:earliest_pos]
            # Count newlines in text to update lineno
            newlines = text.count('\n')
            lineno += newlines
            if text:
                tokens.append(Token("text", text, lineno))

        # Process the tag
        if tag_type == 'comment':
            # Find end delimiter
            end_pos = source.find(TAG_END_COMMENT, pos + len(tag_str))
            if end_pos == -1:
                # Tag not closed
                raise TemplateSyntaxError("Unclosed comment", lineno)
            # Advance pos past the end of the comment
            pos = end_pos + len(TAG_END_COMMENT)
            # Update lineno
            skipped = source[earliest_pos:pos]
            lineno += skipped.count('\n')

        elif tag_type == 'var':
            # Find end delimiter
            end_pos = source.find(TAG_END_VAR, pos + len(tag_str))
            if end_pos == -1:
                raise TemplateSyntaxError("Unclosed expression", lineno)

            # Extract content
            content = source[pos + len(tag_str):end_pos].strip()

            tokens.append(Token("var", content, lineno))

            pos = end_pos + len(TAG_END_VAR)
            skipped = source[earliest_pos:pos]
            lineno += skipped.count('\n')

        elif tag_type == 'block':
            # Find end delimiter
            end_pos = source.find(TAG_END_BLOCK, pos + len(tag_str))
            if end_pos == -1:
                raise TemplateSyntaxError("Unclosed block", lineno)

            # Extract content
            content = source[pos + len(tag_str):end_pos].strip()

            tokens.append(Token("block", content, lineno))

            pos = end_pos + len(TAG_END_BLOCK)
            skipped = source[earliest_pos:pos]
            lineno += skipped.count('\n')

    return tokens
