import re
from tmpl.lexer import tokenize, TemplateSyntaxError, Token


# Reserved words for variable names
RESERVED_NAMES = {'and', 'or', 'not', 'in'}

# Filter names and their properties
# arg_types: None, 'str', 'int'
FILTERS = {
    'upper': None,
    'lower': None,
    'trim': None,
    'length': None,
    'first': None,
    'last': None,
    'reverse': None,
    'join': 'str',
    'default': 'default', # Special handling
    'truncate': 'int',
    'items': None,
}

# Regex for variable path
NAME_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')


class TextNode:
    def __init__(self, text: str, lineno: int):
        self.text = text
        self.lineno = lineno

class VarNode:
    def __init__(self, expr_ast, lineno: int):
        self.expr_ast = expr_ast
        self.lineno = lineno

class IfNode:
    def __init__(self, lineno: int):
        self.branches = [] # List of (cond_ast, body_nodes)
        self.else_body = None # List of nodes
        self.lineno = lineno

class ForNode:
    def __init__(self, var_name: str, expr_ast, lineno: int):
        self.var_name = var_name
        self.expr_ast = expr_ast
        self.body = []
        self.else_body = []
        self.lineno = lineno


def parse(source: str) -> list:
    """
    Parse the source template into a list of nodes.
    Raises TemplateSyntaxError on syntax errors.
    """
    tokens = tokenize(source)
    nodes, _ = _parse_tokens_v2(tokens, 0, None)
    return nodes

def _parse_tokens_v2(tokens: list[Token], idx: int, stop_on: list[str] | None = None) -> tuple[list, int]:
    """
    Parse nodes from tokens[idx:].
    If stop_on is provided, stop when a block token matches one of the strings in stop_on.
    Returns (nodes, next_idx).
    """
    nodes = []

    while idx < len(tokens):
        tok = tokens[idx]

        if tok.kind == 'text':
            nodes.append(TextNode(tok.value, tok.lineno))
            idx += 1

        elif tok.kind == 'var':
            ast, _ = _parse_expression(tok.value, tok.lineno, idx+1)
            nodes.append(VarNode(ast, tok.lineno))
            idx += 1

        elif tok.kind == 'block':
            content = tok.value.strip()
            lineno = tok.lineno

            # Check for stop condition
            if stop_on and content in stop_on:
                return nodes, idx

            # Check for block closers that shouldn't be here at this level
            if content == 'endif':
                raise TemplateSyntaxError("'endif' outside of block", lineno)
            elif content == 'endfor':
                raise TemplateSyntaxError("'endfor' outside of block", lineno)
            elif content == 'else':
                raise TemplateSyntaxError("'else' outside of block", lineno)
            elif content.startswith('elif '):
                raise TemplateSyntaxError("'elif' outside of block", lineno)
            elif content == 'elif':
                raise TemplateSyntaxError("Empty elif condition", lineno)

            # Check for block openers
            if content.startswith('if '):
                cond_str = content[3:].strip()
                if not cond_str:
                    raise TemplateSyntaxError("Empty if condition", lineno)

                if_node = IfNode(lineno)
                cond_ast, _ = _parse_condition(cond_str, lineno)

                # Parse body until else, elif, endif
                branch_nodes, idx = _parse_tokens_v2(tokens, idx + 1, ['else', 'elif', 'endif'])
                if_node.branches.append((cond_ast, branch_nodes))

                # Parse elif/else/endif
                while idx < len(tokens):
                    next_tok = tokens[idx]
                    if next_tok.kind != 'block':
                        raise TemplateSyntaxError("Expected elif, else, or endif", next_tok.lineno)

                    next_content = next_tok.value.strip()
                    next_lineno = next_tok.lineno

                    if next_content == 'else':
                        idx += 1
                        else_nodes, idx = _parse_tokens_v2(tokens, idx, ['endif'])
                        if_node.else_body = else_nodes
                    elif next_content.startswith('elif '):
                        cond_str = next_content[5:].strip()
                        if not cond_str:
                            raise TemplateSyntaxError("Empty elif condition", next_lineno)

                        idx += 1
                        cond_ast, _ = _parse_condition(cond_str, next_lineno)
                        branch_nodes, idx = _parse_tokens_v2(tokens, idx, ['elif', 'else', 'endif'])
                        if_node.branches.append((cond_ast, branch_nodes))
                    elif next_content == 'elif':
                        raise TemplateSyntaxError("Empty elif condition", next_lineno)
                    elif next_content == 'endif':
                        idx += 1
                        break
                    else:
                        raise TemplateSyntaxError(f"Expected elif, else, or endif, got '{next_content}'", next_lineno)

                nodes.append(if_node)

            elif content.startswith('for '):
                if ' in ' not in content:
                    raise TemplateSyntaxError("Malformed for statement", lineno)

                parts = content.split(' in ', 1)
                var_name = parts[0].strip()
                expr_str = parts[1].strip()

                if not var_name:
                    raise TemplateSyntaxError("Malformed for statement", lineno)
                if not NAME_RE.match(var_name):
                    raise TemplateSyntaxError(f"Invalid for variable name '{var_name}'", lineno)
                if var_name in RESERVED_NAMES:
                    raise TemplateSyntaxError(f"'{var_name}' is a reserved name", lineno)

                expr_ast, _ = _parse_expression(expr_str, lineno, idx+1)

                for_node = ForNode(var_name, expr_ast, lineno)

                # Parse body until else or endfor
                body_nodes, idx = _parse_tokens_v2(tokens, idx + 1, ['else', 'endfor'])
                for_node.body = body_nodes

                # Check for else
                if idx < len(tokens):
                    next_tok = tokens[idx]
                    if next_tok.kind == 'block' and next_tok.value.strip() == 'else':
                        idx += 1
                        else_nodes, idx = _parse_tokens_v2(tokens, idx, ['endfor'])
                        for_node.else_body = else_nodes

                    # Check for endfor
                    if idx < len(tokens):
                        next_tok = tokens[idx]
                        if next_tok.kind == 'block' and next_tok.value.strip() == 'endfor':
                            idx += 1
                        else:
                            raise TemplateSyntaxError("Expected endfor", next_tok.lineno)
                    else:
                        raise TemplateSyntaxError("Expected endfor", lineno)
                else:
                    raise TemplateSyntaxError("Expected endfor", lineno)

                nodes.append(for_node)

            else:
                raise TemplateSyntaxError(f"Unknown statement '{content}'", lineno)

        else:
            raise TemplateSyntaxError("Unknown token kind", tok.lineno)

    return nodes, idx

def _parse_expression(expr_str: str, lineno: int, idx: int):
    """Parse a value expression string into an AST."""
    ast, _ = _parse_value_expression_tokens(_tokenize_expression(expr_str), 0)
    return ast, idx

def _parse_condition(cond_str: str, lineno: int):
    """Parse a condition string into an AST."""
    tokens = _tokenize_expression(cond_str)
    ast, _ = _parse_or(tokens, 0)
    return ast, lineno

def _tokenize_expression(expr_str):
    """
    Tokenize an expression string.
    Tokens are: NAME, INT, STR, FILTER, OP.
    """
    tokens = []
    pos = 0
    length = len(expr_str)

    while pos < length:
        char = expr_str[pos]

        # Whitespace
        if char.isspace():
            pos += 1
            continue

        # String literal
        if char in ('"', "'"):
            quote = char
            pos += 1
            start = pos
            while pos < length and expr_str[pos] != quote:
                pos += 1
            if pos >= length:
                raise TemplateSyntaxError("Unterminated string literal", 0) # Lineno will be set by caller if needed, but here 0 is placeholder
            val = expr_str[start:pos]
            tokens.append(('STR', val))
            pos += 1 # Skip closing quote

        # Integer literal (including negative)
        elif char.isdigit() or (char == '-' and pos + 1 < length and expr_str[pos+1].isdigit()):
            start = pos
            if char == '-':
                pos += 1
            while pos < length and expr_str[pos].isdigit():
                pos += 1
            val = int(expr_str[start:pos])
            tokens.append(('INT', val))

        # Name
        elif char.isalpha() or char == '_':
            start = pos
            while pos < length and (expr_str[pos].isalnum() or expr_str[pos] == '.'):
                pos += 1
            val = expr_str[start:pos]
            # Check for reserved words
            if val in RESERVED_NAMES:
                raise TemplateSyntaxError(f"'{val}' is a reserved word", 0)
            tokens.append(('NAME', val))

        # Filter pipe
        elif char == '|':
            tokens.append(('FILTER', '|'))
            pos += 1

        # Comparison operators
        elif expr_str[pos:pos+2] in ('==', '!=', '<=', '>='):
            op = expr_str[pos:pos+2]
            tokens.append(('OP', op))
            pos += 2

        elif char in ('<', '>'):
            op = expr_str[pos]
            tokens.append(('OP', op))
            pos += 1

        # Logical operators
        elif expr_str[pos:pos+2] == 'or' and (pos+2 >= length or not expr_str[pos+2].isalnum()):
            tokens.append(('OP', 'or'))
            pos += 2
        elif expr_str[pos:pos+3] == 'and' and (pos+3 >= length or not expr_str[pos+3].isalnum()):
            tokens.append(('OP', 'and'))
            pos += 3
        elif expr_str[pos:pos+3] == 'not' and (pos+3 >= length or not expr_str[pos+3].isalnum()):
            tokens.append(('OP', 'not'))
            pos += 3
        elif expr_str[pos:pos+2] == 'in' and (pos+2 >= length or not expr_str[pos+2].isalnum()):
            tokens.append(('OP', 'in'))
            pos += 2

        else:
            raise TemplateSyntaxError(f"Unexpected character '{char}'", 0)

    return tokens


class ValueExprNode:
    """Base class for value expressions."""
    lineno: int = 0
    def evaluate(self, ctx):
        raise NotImplementedError

class AtomNode(ValueExprNode):
    def __init__(self, val, lineno: int):
        self.val = val # Variable path string
        self.lineno = lineno

    def evaluate(self, ctx):
        return _evaluate_path(self.val, ctx)

class LiteralStrNode(ValueExprNode):
    def __init__(self, val, lineno: int):
        self.val = val
        self.lineno = lineno

    def evaluate(self, ctx):
        return self.val

class LiteralIntNode(ValueExprNode):
    def __init__(self, val, lineno: int):
        self.val = val
        self.lineno = lineno

    def evaluate(self, ctx):
        return self.val

class FilterNode(ValueExprNode):
    def __init__(self, input_node, filter_name, argument, lineno: int):
        self.input_node = input_node
        self.filter_name = filter_name
        self.argument = argument
        self.lineno = lineno

    def evaluate(self, ctx):
        val = self.input_node.evaluate(ctx)

        # Validate filter
        if self.filter_name not in FILTERS:
            raise TemplateSyntaxError(f"Unknown filter '{self.filter_name}'", self.lineno)

        req_arg_type = FILTERS[self.filter_name]

        # Check argument validity
        if req_arg_type is None:
            if self.argument is not None:
                raise TemplateSyntaxError(f"Filter '{self.filter_name}' takes no argument", self.lineno)
        elif req_arg_type == 'default':
            # Accept any argument
            pass
        else:
            if self.argument is None:
                raise TemplateSyntaxError(f"Filter '{self.filter_name}' requires an argument", self.lineno)

            # Validate argument type
            if req_arg_type == 'int':
                if not isinstance(self.argument, int):
                    raise TemplateSyntaxError(f"Filter '{self.filter_name}' requires an integer argument", self.lineno)
                if self.argument < 0:
                    raise TemplateSyntaxError(f"Filter '{self.filter_name}' requires a non-negative argument", self.lineno)
            elif req_arg_type == 'str':
                if not isinstance(self.argument, str):
                    raise TemplateSyntaxError(f"Filter '{self.filter_name}' requires a string argument", self.lineno)

        # Apply filter
        try:
            if self.filter_name == 'upper':
                return str(val).upper()
            elif self.filter_name == 'lower':
                return str(val).lower()
            elif self.filter_name == 'trim':
                return str(val).strip()
            elif self.filter_name == 'length':
                if val is None:
                    return 0
                return len(val)
            elif self.filter_name == 'first':
                if val is None or len(val) == 0:
                    return None
                return val[0]
            elif self.filter_name == 'last':
                if val is None or len(val) == 0:
                    return None
                return val[-1]
            elif self.filter_name == 'reverse':
                if val is None:
                    return None
                if isinstance(val, str):
                    return val[::-1]
                else:
                    try:
                        return list(reversed(val))
                    except TypeError:
                        raise TemplateRenderError(f"Cannot reverse non-iterable value", self.lineno)
            elif self.filter_name == 'join':
                if val is None:
                    return ''
                sep = self.argument
                try:
                    iter(val)
                except TypeError:
                    raise TemplateRenderError(f"Cannot join non-iterable value", self.lineno)
                return sep.join(str(item) for item in val)
            elif self.filter_name == 'default':
                if val is None or val == '':
                    return self.argument
                return val
            elif self.filter_name == 'truncate':
                s = str(val)
                if len(s) > self.argument:
                    return s[:self.argument] + '...'
                return s
            elif self.filter_name == 'items':
                if val is None:
                    return []
                if not isinstance(val, collections.abc.Mapping):
                    raise TemplateRenderError(f"Cannot use 'items' filter on non-mapping", self.lineno)
                return list(val.items())
            else:
                raise TemplateRenderError(f"Unknown filter '{self.filter_name}'", self.lineno)
        except (TypeError, KeyError, IndexError) as e:
            raise TemplateRenderError(f"Filter '{self.filter_name}' error: {e}", self.lineno)

class ComparisonNode(ValueExprNode):
    def __init__(self, left, op, right, lineno: int):
        self.left = left
        self.op = op
        self.right = right
        self.lineno = lineno

    def evaluate(self, ctx):
        l = self.left.evaluate(ctx)
        r = self.right.evaluate(ctx)

        if self.op == '==':
            return l == r
        elif self.op == '!=':
            return l != r
        elif self.op in ('<', '<=', '>', '>='):
            try:
                if self.op == '<':
                    return l < r
                elif self.op == '<=':
                    return l <= r
                elif self.op == '>':
                    return l > r
                elif self.op == '>=':
                    return l >= r
            except TypeError:
                raise TemplateRenderError(f"Comparison not supported for these types", self.lineno)
        return False

class LogicNode(ValueExprNode):
    def __init__(self, op, left, right, lineno: int):
        self.op = op
        self.left = left
        self.right = right
        self.lineno = lineno

    def evaluate(self, ctx):
        if self.op == 'not':
            return not _get_truthiness(self.left.evaluate(ctx))
        elif self.op == 'and':
            l = _get_truthiness(self.left.evaluate(ctx))
            if not l:
                return False
            return _get_truthiness(self.right.evaluate(ctx))
        elif self.op == 'or':
            l = _get_truthiness(self.left.evaluate(ctx))
            if l:
                return True
            return _get_truthiness(self.right.evaluate(ctx))
        return False


def _parse_value_expression_tokens(tokens, idx):
    """
    Parse value expression tokens.
    Returns (AST, next_idx).
    """
    return _parse_or(tokens, idx)

def _parse_or(tokens, idx):
    left, idx = _parse_and(tokens, idx)
    while idx < len(tokens) and tokens[idx][0] == 'OP' and tokens[idx][1] == 'or':
        idx += 1
        right, idx = _parse_and(tokens, idx)
        left = LogicNode('or', left, right, left.lineno if hasattr(left, 'lineno') else 0)
    return left, idx

def _parse_and(tokens, idx):
    left, idx = _parse_not(tokens, idx)
    while idx < len(tokens) and tokens[idx][0] == 'OP' and tokens[idx][1] == 'and':
        idx += 1
        right, idx = _parse_not(tokens, idx)
        left = LogicNode('and', left, right, left.lineno if hasattr(left, 'lineno') else 0)
    return left, idx

def _parse_not(tokens, idx):
    if idx < len(tokens) and tokens[idx][0] == 'OP' and tokens[idx][1] == 'not':
        idx += 1
        right, idx = _parse_not(tokens, idx)
        return LogicNode('not', right, None, right.lineno if hasattr(right, 'lineno') else 0), idx
    return _parse_comparison(tokens, idx)

def _parse_comparison(tokens, idx):
    left, idx = _parse_atom_filter(tokens, idx)

    if idx < len(tokens) and tokens[idx][0] == 'OP' and tokens[idx][1] in ('==', '!=', '<', '<=', '>', '>='):
        op = tokens[idx][1]
        idx += 1
        right, idx = _parse_atom_filter(tokens, idx)
        return ComparisonNode(left, op, right, left.lineno if hasattr(left, 'lineno') else 0), idx

    return left, idx

def _parse_atom_filter(tokens, idx):
    if idx >= len(tokens):
        raise TemplateSyntaxError("Expected value", 0)

    token = tokens[idx]

    if token[0] == 'STR':
        ast = LiteralStrNode(token[1], 0)
        idx += 1
    elif token[0] == 'INT':
        ast = LiteralIntNode(token[1], 0)
        idx += 1
    elif token[0] == 'NAME':
        ast = AtomNode(token[1], 0)
        idx += 1
    else:
        raise TemplateSyntaxError("Expected value", 0)

    # Parse filters
    while idx < len(tokens) and tokens[idx][0] == 'FILTER':
        idx += 1
        if idx >= len(tokens):
            raise TemplateSyntaxError("Expected filter name", 0)

        filter_token = tokens[idx]
        if filter_token[0] != 'NAME':
            raise TemplateSyntaxError("Expected filter name", 0)

        filter_name = filter_token[1]
        idx += 1

        argument = None
        if idx < len(tokens) and tokens[idx][0] == 'OP' and tokens[idx][1] == ':':
            idx += 1
            if idx >= len(tokens):
                raise TemplateSyntaxError("Expected filter argument", 0)

            arg_token = tokens[idx]
            if arg_token[0] == 'STR':
                argument = arg_token[1]
                idx += 1
            elif arg_token[0] == 'INT':
                argument = arg_token[1]
                idx += 1
            else:
                raise TemplateSyntaxError("Expected filter argument", 0)

        ast = FilterNode(ast, filter_name, argument, ast.lineno)

    return ast, idx

def _evaluate_path(name_str, ctx):
    """
    Evaluate a variable path like 'user.name' or 'rows.0'.
    Returns the value.
    """
    parts = name_str.split('.')
    val = ctx.get(parts[0], None)

    for part in parts[1:]:
        if val is None:
            return None

        # Try as integer index
        if part.isdigit():
            idx = int(part)
            if isinstance(val, (list, tuple)):
                if 0 <= idx < len(val):
                    val = val[idx]
                else:
                    return None
            elif isinstance(val, collections.abc.Mapping):
                # Look up as string key
                val = val.get(part, None)
            else:
                return None
        else:
            # Try as attribute or mapping key
            if isinstance(val, collections.abc.Mapping):
                val = val.get(part, None)
            elif isinstance(val, object):
                # Check attribute
                if part.startswith('_'):
                    val = None
                else:
                    val = getattr(val, part, None)
            else:
                return None

    return val


def _get_truthiness(val):
    if val is None:
        return False
    if isinstance(val, bool):
        return val
    if isinstance(val, (int, float)):
        return val != 0
    if isinstance(val, str):
        return len(val) > 0
    if isinstance(val, (list, tuple, dict, set)):
        return len(val) > 0
    return bool(val)


