from collections.abc import Mapping
from tmpl.parser import parse, TextNode, VarNode, IfNode, ForNode
from tmpl.lexer import TemplateSyntaxError, TemplateRenderError
import collections.abc


class Template:
    def __init__(self, source: str):
        self.nodes = parse(source)

    def render(self, context: dict | None = None, **kwargs) -> str:
        ctx = {}
        if context:
            ctx.update(context)
        ctx.update(kwargs)
        return self._render_nodes(self.nodes, ctx)

    def _render_nodes(self, nodes, ctx):
        output = []
        for node in nodes:
            output.append(node.render(ctx))
        return ''.join(output)


def render(source: str, context: dict | None = None, **kwargs) -> str:
    return Template(source).render(context, **kwargs)


# Node Render Methods
def _render_text_node(self, ctx):
    return self.text

def _render_var_node(self, ctx):
    val = self.expr_ast.evaluate(ctx)
    if val is None:
        return ''
    return str(val)

def _render_if_node(self, ctx):
    for cond_ast, body in self.branches:
        if _get_truthiness(cond_ast.evaluate(ctx)):
            return self._render_nodes(body, ctx)
    if self.else_body is not None:
        return self._render_nodes(self.else_body, ctx)
    return ''

def _render_for_node(self, ctx):
    items = self.expr_ast.evaluate(ctx)
    if items is None:
        items = []

    # Determine iteration order
    if isinstance(items, Mapping):
        iter_items = list(items.keys())
    elif isinstance(items, (list, tuple)):
        iter_items = list(items)
    else:
        # Check if iterable
        try:
            iter_items = list(items)
        except TypeError:
            raise TemplateRenderError(f"'{self.var_name}' is not iterable", self.lineno)

    if not iter_items:
        if self.else_body is not None:
            return self._render_nodes(self.else_body, ctx)
        return ''

    # Prepare loop context
    loop_ctx = {
        'index': 1,
        'index0': 0,
        'first': True,
        'last': False,
        'length': len(iter_items)
    }

    output = []
    total = len(iter_items)

    for i, item in enumerate(iter_items):
        # Update loop metadata
        loop_ctx['index'] = i + 1
        loop_ctx['index0'] = i
        loop_ctx['first'] = (i == 0)
        loop_ctx['last'] = (i == total - 1)

        # Create local context with variable and loop
        local_ctx = dict(ctx)
        local_ctx[self.var_name] = item
        local_ctx['loop'] = loop_ctx

        output.append(self._render_nodes(self.body, local_ctx))

    return ''.join(output)

def _get_truthiness(val):
    if val is None:
        return False
    if isinstance(val, bool):
        return val
    if isinstance(val, (int, float)):
        return val != 0
    if isinstance(val, str):
        return len(val) > 0
    if isinstance(val, (list, tuple, dict, set)):
        return len(val) > 0
    return bool(val)


# Attach methods to classes
TextNode.render = _render_text_node
VarNode.render = _render_var_node
IfNode.render = _render_if_node
ForNode.render = _render_for_node
