ERROR_CYCLE = ErrorValue("#CYCLE!")


class FormulaError(ValueError):
    """Error raised when a formula is syntactically invalid."""

    pass


# --- Syntax Tree Nodes ---

class NumberNode:
    def __init__(self, value: Union[int, float]):
        self.value = value


class RefNode:
    def __init__(self, name: str):
        self.name = name


class UnaryNode:
    def __init__(self, operator: str, operand):
        self.operator = operator  # '+' or '-'
        self.operand = operand


class BinaryNode:
    def __init__(self, operator: str, left, right):
        self.operator = operator  # '+', '-', '*', '/'
        self.left = left
        self.right = right


# --- Parser ---

class Parser:
    """Recursive descent parser for the formula grammar."""

    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.length = len(text)

    def peek(self) -> str:
        if self.pos < self.length:
            return self.text[self.pos]
        return ''

    def consume(self, expected: str = None) -> str:
        if self.pos >= self.length:
            raise FormulaError("Unexpected end of formula")
        ch = self.text[self.pos]
        if expected and ch != expected:
            raise FormulaError(f"Expected '{expected}' but got '{ch}'")
        self.pos += 1
        return ch

    def skip_whitespace(self):
        while self.pos < self.length and self.text[self.pos].isspace():
            self.pos += 1

    def parse(self):
        self.skip_whitespace()
        if self.pos >= self.length:
            raise FormulaError("Empty formula")
        node = self.parse_expr()
        self.skip_whitespace()
        if self.pos < self.length:
            raise FormulaError("Unexpected characters after expression")
        return node

    def parse_expr(self):
        """expr := term {(+ | -) term}"""
        left = self.parse_term()
        while True:
            self.skip_whitespace()
            if self.pos < self.length and self.text[self.pos] in ('+', '-'):
                op = self.consume()
                right = self.parse_term()
                left = BinaryNode(op, left, right)
            else:
                break
        return left

    def parse_term(self):
        """term := unary {(* | /) unary}"""
        left = self.parse_unary()
        while True:
            self.skip_whitespace()
            if self.pos < self.length and self.text[self.pos] in ('*', '/'):
                op = self.consume()
                right = self.parse_unary()
                left = BinaryNode(op, left, right)
            else:
                break
        return left

    def parse_unary(self):
        """unary := (+ | -) unary | number | ref | ( expr )"""
        self.skip_whitespace()
        if self.pos >= self.length:
            raise FormulaError("Incomplete expression")

        ch = self.peek()
        if ch in ('+', '-'):
            op = self.consume()
            operand = self.parse_unary()
            return UnaryNode(op, operand)
        elif ch == '(':
            self.consume('(')
            node = self.parse_expr()
            self.skip_whitespace()
            self.consume(')')
            return node
        else:
            return self.parse_number_or_ref()

    def parse_number_or_ref(self):
        """Parse a number or a reference."""
        self.skip_whitespace()
        if self.pos >= self.length:
            raise FormulaError("Incomplete expression")

        ch = self.peek()
        if ch.isdigit():
            return self.parse_number()
        elif ch.isalpha():
            return self.parse_ref()
        else:
            raise FormulaError(f"Unexpected character '{ch}'")

    def parse_number(self):
        """Parse a number: digits [. digits]"""
        self.skip_whitespace()
        start = self.pos
        while self.pos < self.length and self.text[self.pos].isdigit():
            self.pos += 1
        if self.pos >= self.length or self.text[self.pos] != '.':
            # Just digits
            num_str = self.text[start:self.pos]
            if not num_str:
                raise FormulaError("Invalid number")
            return NumberNode(int(num_str))
        else:
            # Has decimal point
            self.pos += 1  # skip '.'
            has_digits = False
            while self.pos < self.length and self.text[self.pos].isdigit():
                has_digits = True
                self.pos += 1
            if not has_digits:
                raise FormulaError("Invalid number: no digits after decimal point")
            num_str = self.text[start:self.pos]
            return NumberNode(float(num_str))

    def parse_ref(self):
        """Parse a reference: letters digits"""
        self.skip_whitespace()
        start = self.pos
        while self.pos < self.length and self.text[self.pos].isalpha():
            self.pos += 1
        letters = self.text[start:self.pos]
        if not letters:
            raise FormulaError("Invalid reference: no letters")

        # Check for more than one letter
        if len(letters) > 1:
            raise FormulaError(f"Invalid reference: '{letters}' has more than one letter")

        # Check column is A-Z
        col = letters.upper()
        if col < 'A' or col > 'Z':
            raise FormulaError(f"Invalid column: '{col}'")

        # Now parse digits
        if self.pos >= self.length or not self.text[self.pos].isdigit():
            raise FormulaError(f"Invalid reference: missing row number for '{col}'")

        row_start = self.pos
        while self.pos < self.length and self.text[self.pos].isdigit():
            self.pos += 1
        row_str = self.text[row_start:self.pos]

        if not row_str:
            raise FormulaError(f"Invalid reference: no digits after column '{col}'")

        # Check for leading zeros
        if len(row_str) > 1 and row_str[0] == '0':
            raise FormulaError(f"Invalid reference: row '{row_str}' has leading zero")

        row = int(row_str)
        if row == 0:
            raise FormulaError(f"Invalid reference: row 0 is not allowed")
        if row > 999:
            raise FormulaError(f"Invalid reference: row {row} is out of range (1-999)")

        name = f"{col}{row}"
        return RefNode(name)


def parse_formula(source: str):
    """Parse a formula (the text after '=') and return a syntax tree."""
    if not source or not source.strip():
        raise FormulaError("Empty formula")
    parser = Parser(source)
    return parser.parse()


def references(tree) -> Set[str]:
    """Return the set of upper-case cell names referenced in the formula tree."""
    refs = set()
    _collect_refs(tree, refs)
    return refs


def _collect_refs(node, refs: Set[str]):
    if isinstance(node, RefNode):
        refs.add(node.name)
    elif isinstance(node, UnaryNode):
        _collect_refs(node.operand, refs)
    elif isinstance(node, BinaryNode):
        _collect_refs(node.left, refs)
        _collect_refs(node.right, refs)


def evaluate(tree, lookup) -> Any:
    """Evaluate a formula tree given a lookup function.

    lookup(name) returns the cell's current value.
    Returns the computed value or an ErrorValue.
    """
    try:
        return _eval_node(tree, lookup)
    except FormulaError:
        raise
    except Exception:
        return ERROR_ERROR


def _eval_node(node, lookup):
    if isinstance(node, NumberNode):
        return node.value
    elif isinstance(node, RefNode):
        val = lookup(node.name)
        if val is None:
            return 0
        elif isinstance(val, ErrorValue):
            return val
        elif isinstance(val, (int, float, str)):
            return val
        else:
            return ERROR_ERROR
    elif isinstance(node, UnaryNode):
        val = _eval_node(node.operand, lookup)
        if isinstance(val, ErrorValue):
            return val
        if isinstance(val, str):
            return ERROR_ERROR
        if not isinstance(val, (int, float)):
            return ERROR_ERROR
        if node.operator == '+':
            return val
        else:  # '-'
            return -val
    elif isinstance(node, BinaryNode):
        left_val = _eval_node(node.left, lookup)
        if isinstance(left_val, ErrorValue):
            return left_val
        right_val = _eval_node(node.right, lookup)
        if isinstance(right_val, ErrorValue):
            return right_val

        # Check for text operands
        if isinstance(left_val, str) or isinstance(right_val, str):
            return ERROR_ERROR

        # Both should be numbers now
        if not isinstance(left_val, (int, float)) or not isinstance(right_val, (int, float)):
            return ERROR_ERROR

        if node.operator == '+':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val + right_val
            else:
                return float(left_val) + float(right_val)
        elif node.operator == '-':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val - right_val
            else:
                return float(left_val) - float(right_val)
        elif node.operator == '*':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val * right_val
            else:
                return float(left_val) * float(right_val)
        elif node.operator == '/':
            if right_val == 0:
                return ERROR_ERROR
            # Division always gives float
            return float(left_val) / float(right_val)
        else:
            return ERROR_ERROR
