# sheet/graph.py

from typing import Dict, Iterable, Set


class DependencyGraph:
    """Tracks dependencies between cells."""

    def __init__(self):
        # precedents: cell -> set of cells it refers to
        self._precedents: Dict[str, Set[str]] = {}
        # dependents: cell -> set of cells that refer to it
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """Replace the precedents of cell with the given iterable."""
        precedents_set = set(precedents)
        old_precedents = self._precedents.get(cell, set())

        # Remove old dependencies from dependents
        for old_prec in old_precedents:
            if old_prec in self._dependents:
                self._dependents[old_prec].discard(cell)
                if not self._dependents[old_prec]:
                    del self._dependents[old_prec]

        # Set new precedents
        self._precedents[cell] = precedents_set

        # Add new dependencies
        for new_prec in precedents_set:
            if new_prec not in self._dependents:
                self._dependents[new_prec] = set()
            self._dependents[new_prec].add(cell)

        # Clean up empty entries in precedents map
        if not precedents_set:
            if cell in self._precedents:
                del self._precedents[cell]

    def precedents(self, cell: str) -> Set[str]:
        """Return the direct precedents of a cell."""
        return set(self._precedents.get(cell, set()))

    def dependents(self, cell: str) -> Set[str]:
        """Return the direct dependents of a cell."""
        return set(self._dependents.get(cell, set()))

    def all_dependents(self, cell: str) -> Set[str]:
        """Return all cells that depend on cell, directly or indirectly.

        Contains cell itself only if cell is on a cycle.
        """
        result = set()
        visited = set()
        stack = [cell]

        while stack:
            current = stack.pop()
            if current in visited:
                continue
            visited.add(current)

            # Get dependents of current
            deps = self.dependents(current)
            for dep in deps:
                if dep == cell:
                    # Found a cycle back to cell
                    result.add(cell)
                if dep not in visited:
                    stack.append(dep)
                    result.add(dep)

        return result

    def cycle_cells(self) -> Set[str]:
        """Return all cells that lie on a cycle."""
        cycle_cells_set = set()

        # A cell is on a cycle if it can reach itself following its precedents
        for cell in self._precedents:
            if self._can_reach(cell, cell, set()):
                cycle_cells_set.add(cell)

        return cycle_cells_set

    def _can_reach(self, start: str, target: str, visited: Set[str]) -> bool:
        """Check if target is reachable from start by following precedents."""
        if start == target:
            return True
        if start in visited:
            return False
        visited.add(start)

        for prec in self.precedents(start):
            if self._can_reach(prec, target, visited):
                return True
        return False
