# sheet/sheet.py

import re
from typing import Any, Dict, List, Optional, Set

from .formula import (
    FormulaError,
    ErrorValue,
    parse_formula,
    references,
    evaluate,
    ERROR_CYCLE,
)
from .graph import DependencyGraph


def _validate_cell_name(name: str) -> str:
    """Validate and normalize a cell name. Returns upper-case name or raises ValueError."""
    if not isinstance(name, str):
        raise ValueError(f"Cell name must be a string, got {type(name)}")

    name_upper = name.upper()
    # Must be exactly one letter followed by digits
    if len(name_upper) < 2:
        raise ValueError(f"Invalid cell name: '{name}'")

    col = name_upper[0]
    if col < 'A' or col > 'Z':
        raise ValueError(f"Invalid column in cell name: '{name}'")

    row_str = name_upper[1:]
    if not row_str.isdigit():
        raise ValueError(f"Invalid row in cell name: '{name}'")

    row = int(row_str)
    if row < 1 or row > 999:
        raise ValueError(f"Row out of range in cell name: '{name}'")

    # Check for leading zeros
    if len(row_str) > 1 and row_str[0] == '0':
        raise ValueError(f"Leading zero in row: '{name}'")

    return name_upper


def _parse_number_string(raw: str) -> Optional[object]:
    """Check if raw is a number string (optional minus, digits, optional decimal).
    Returns int or float if it matches, else None."""
    # Optional '-' followed by digits [. digits]
    match = re.match(r'^-?\d+(\.\d+)?$', raw)
    if match:
        if '.' in raw:
            return float(raw)
        else:
            return int(raw)
    return None


def _is_formula_cell_name(name: str) -> bool:
    """Check if a cell name is within the valid range A1-Z999."""
    if len(name) < 2:
        return False
    col = name[0]
    if col < 'A' or col > 'Z':
        return False
    row_str = name[1:]
    if not row_str.isdigit():
        return False
    row = int(row_str)
    if row < 1 or row > 999:
        return False
    return True


class Sheet:
    """A spreadsheet engine."""

    def __init__(self):
        self._raw: Dict[str, str] = {}
        self._values: Dict[str, Any] = {}
        self._graph = DependencyGraph()
        self.evaluations: int = 0
        self._cycle_cells: Set[str] = set()

    def set(self, name: str, raw: str) -> List[str]:
        """Store the cell's input and return cells whose values may have changed."""
        if not isinstance(raw, str):
            raise TypeError("raw must be a str")

        cell = _validate_cell_name(name)

        if not _is_formula_cell_name(cell):
            raise ValueError(f"Cell name out of range: '{name}'")

        # Store raw input
        self._raw[cell] = raw

        # Save state to allow rollback if parse fails
        old_values = {}
        if cell in self._values:
            old_values[cell] = self._values[cell]
            del self._values[cell]
        else:
            old_values[cell] = None # To ensure it's removed from _values if it was there

        old_precedents = self._graph.precedents(cell)
        self._graph.set_dependencies(cell, [])

        # Determine the new type: formula, number, or text
        is_formula = False
        is_number = False
        parsed_value = None
        formula_tree = None

        stripped = raw.strip()

        if stripped == '':
            # Empty cell
            self._values[cell] = None
        elif stripped.startswith('='):
            # Formula
            formula_text = stripped[1:]
            try:
                formula_tree = parse_formula(formula_text)
            except FormulaError:
                # Re-raise and leave sheet unchanged
                # Rollback
                self._values = old_values
                self._graph.set_dependencies(cell, old_precedents)
                raise

            # Get references
            new_precedents = references(formula_tree)
            self._graph.set_dependencies(cell, new_precedents)

            # Check for cycles involving this cell
            self._update_cycle_cells()
            if cell in self._cycle_cells:
                self._values[cell] = ERROR_CYCLE
            else:
                is_formula = True
                self._values[cell] = None  # Will be evaluated later
        elif _parse_number_string(stripped) is not None:
            # Number
            num = _parse_number_string(stripped)
            self._values[cell] = num
        else:
            # Text
            self._values[cell] = raw

        # Now, if it was a formula, we need to evaluate it and all dependents
        if is_formula:
            # Determine the set of cells to evaluate
            # The cell itself plus all its dependents
            cells_to_eval = {cell}
            cells_to_eval.update(self._graph.all_dependents(cell))

            # Filter out cells that are on cycles
            cells_to_eval -= self._cycle_cells

            # Filter out cells that don't have formulas
            cells_to_eval = {c for c in cells_to_eval if self._is_formula_cell(c)}

            # Topological sort: evaluate in order such that precedents are evaluated before dependents
            order = self._topological_sort(cells_to_eval)

            for c in order:
                if c in self._cycle_cells:
                    self._values[c] = ERROR_CYCLE
                    continue
                if not self._is_formula_cell(c):
                    continue
                # Evaluate the formula
                self._evaluate_cell(c)

            # Convert cells to list in row-major order
            result = sorted(cells_to_eval, key=lambda n: (_row_num(n), _col_letter(n)))
            return result
        else:
            # No formula change, but we still need to return dependents of this cell
            # Actually, the spec says: "returns the cells whose value may have changed,
            # in row-major order: the cell itself plus every cell in its all_dependents."
            # But only if it was a formula that changed? Let me re-read.
            # "set evaluates each formula cell in its returned list that is not on a cycle exactly once"
            # And: "A cell on a cycle has the value #CYCLE! and is not evaluated."
            #
            # If it's not a formula (number or text), do we still propagate changes?
            # The spec says: "After every set, every cell's value is as if the whole sheet had been calculated from scratch."
            # But the efficiency requirement: "set evaluates each formula cell in its returned list that is not on a cycle exactly once"
            #
            # Let me re-read: "It returns the cells whose value may have changed, in row-major order: the cell itself plus every cell in its all_dependents."
            #
            # So even for a number/text change, we should return the cell and all its dependents.
            # But do we evaluate them? Only if they are formulas.
            #
            # So for number/text changes, we still need to propagate and evaluate dependents.
            cells_to_eval = {cell}
            cells_to_eval.update(self._graph.all_dependents(cell))

            # Filter out cycle cells
            cells_to_eval -= self._cycle_cells

            # Only evaluate formula cells
            formula_cells_to_eval = {c for c in cells_to_eval if self._is_formula_cell(c)}

            if formula_cells_to_eval:
                order = self._topological_sort(formula_cells_to_eval)
                for c in order:
                    if c in self._cycle_cells:
                        self._values[c] = ERROR_CYCLE
                        continue
                    if not self._is_formula_cell(c):
                        continue
                    self._evaluate_cell(c)

            result = sorted(cells_to_eval, key=lambda n: (_row_num(n), _col_letter(n)))
            return result

    def _is_formula_cell(self, cell: str) -> bool:
        """Check if a cell currently holds a formula."""
        raw = self._raw.get(cell, '')
        return raw.strip().startswith('=')

    def _evaluate_cell(self, cell: str):
        """Evaluate a formula cell."""
        raw = self._raw.get(cell, '')
        if not raw.strip().startswith('='):
            return
        formula_text = raw.strip()[1:]
        tree = parse_formula(formula_text)

        def lookup(name: str):
            val = self._values.get(name)
            if val is None:
                return None
            return val

        result = evaluate(tree, lookup)
        self._values[cell] = result
        self.evaluations += 1

    def _update_cycle_cells(self):
        """Recalculate which cells are on cycles."""
        self._cycle_cells = self._graph.cycle_cells()

    def _topological_sort(self, cells: Set[str]) -> List[str]:
        """Topological sort of cells based on their precedents, only considering cells in the set."""
        # Build adjacency for only these cells
        # We need to evaluate precedents before dependents
        in_degree = {c: 0 for c in cells}
        adj = {c: [] for c in cells}

        for c in cells:
            prec = self._graph.precedents(c)
            for p in prec:
                if p in cells:
                    adj[p].append(c)
                    in_degree[c] += 1

        # Kahn's algorithm
        queue = [c for c in cells if in_degree[c] == 0]
        result = []

        # Sort queue for determinism (row-major order)
        queue.sort(key=lambda n: (_row_num(n), _col_letter(n)))

        while queue:
            # Pick the first in row-major order
            queue.sort(key=lambda n: (_row_num(n), _col_letter(n)))
            current = queue.pop(0)
            result.append(current)

            for neighbor in adj[current]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        # If there are still cells left, it means there's a cycle among the remaining cells
        # But we already filtered out cycle cells, so this shouldn't happen
        if len(result) != len(cells):
            # Add remaining cells in row-major order
            remaining = set(cells) - set(result)
            result.extend(sorted(remaining, key=lambda n: (_row_num(n), _col_letter(n))))

        return result

    def get(self, name: str) -> Any:
        """Return the cell's value."""
        cell = _validate_cell_name(name)
        if not _is_formula_cell_name(cell):
            raise ValueError(f"Cell name out of range: '{name}'")
        return self._values.get(cell, None)

    def raw(self, name: str) -> str:
        """Return the input last stored."""
        cell = _validate_cell_name(name)
        if not _is_formula_cell_name(cell):
            raise ValueError(f"Cell name out of range: '{name}'")
        return self._raw.get(cell, '')

    def cells(self) -> List[str]:
        """Return the non-empty cells in row-major order."""
        result = []
        for cell in self._raw:
            if cell in self._values and self._values[cell] is not None:
                result.append(cell)
        result.sort(key=lambda n: (_row_num(n), _col_letter(n)))
        return result


def _row_num(name: str) -> int:
    return int(name[1:])


def _col_letter(name: str) -> str:
    return name[0]
